def combination_sum2(candidates, target):
    candidates.sort()
    res, path = [], []

    def dfs(i, remaining):
        if remaining == 0:
            res.append(path[:])
            return
        for j in range(i, len(candidates)):
            if j > i and candidates[j] == candidates[j - 1]:
                continue               # skip sibling duplicates
            if candidates[j] > remaining:
                break                  # sorted: nothing later fits either
            path.append(candidates[j])
            dfs(j + 1, remaining - candidates[j])   # each element used once
            path.pop()

    dfs(0, target)
    return res

