from itertools import product

def generate_parenthesis(n):
    def valid(s):
        balance = 0
        for ch in s:
            balance += 1 if ch == '(' else -1
            if balance < 0:
                return False
        return balance == 0

    return [''.join(p) for p in product('()', repeat=2 * n) if valid(p)]   # 2^(2n) strings

