def letter_combinations(digits):
    if not digits:
        return []
    keypad = {'2': 'abc', '3': 'def', '4': 'ghi', '5': 'jkl',
              '6': 'mno', '7': 'pqrs', '8': 'tuv', '9': 'wxyz'}
    res, path = [], []

    def dfs(i):                        # i = which digit we are choosing for
        if i == len(digits):
            res.append(''.join(path))
            return
        for ch in keypad[digits[i]]:
            path.append(ch)
            dfs(i + 1)
            path.pop()

    dfs(0)
    return res

def letter_combinations(digits):
    if not digits:
        return []
    keypad = {'2': 'abc', '3': 'def', '4': 'ghi', '5': 'jkl',
              '6': 'mno', '7': 'pqrs', '8': 'tuv', '9': 'wxyz'}
    res = ['']
    for d in digits:                   # extend every partial string by each letter
        res = [prefix + ch for prefix in res for ch in keypad[d]]
    return res

