def subsets_with_dup(nums):
    nums.sort()
    res, path = [], []

    def dfs(start):
        res.append(path[:])
        for j in range(start, len(nums)):
            if j > start and nums[j] == nums[j - 1]:
                continue               # same value already tried at this depth
            path.append(nums[j])
            dfs(j + 1)
            path.pop()

    dfs(0)
    return res
